import { IEvaluatedProgram, Program_getListOfDays } from "../models/program";

const weekdayNames = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

function normalizeDayName(value?: string): string {
  return (value || "").toLowerCase().replace(/[^a-z]/g, "");
}

export function PlanDayUtils_getCalendarDayName(date: Date = new Date()): string {
  return weekdayNames[date.getDay()] || weekdayNames[0];
}

export function PlanDayUtils_findCalendarDay(program: IEvaluatedProgram, date: Date = new Date()): number | undefined {
  const todayName = normalizeDayName(PlanDayUtils_getCalendarDayName(date));
  const days = Program_getListOfDays(program);
  for (let index = 0; index < days.length; index += 1) {
    const [, dayName] = days[index];
    if (normalizeDayName(dayName).includes(todayName)) {
      return index + 1;
    }
  }
  return undefined;
}
