import { JSX, useEffect, useState } from "react";
import { IDispatch } from "../ducks/types";
import { IStorage } from "../types";
import { Button } from "./button";
import { MenuItemEditable } from "./menuItemEditable";
import { MenuItemWrapper } from "./menuItem";
import { GroupHeader } from "./groupHeader";
import {
  PraxonCloud_getLatestSnapshot,
  PraxonCloud_getSession,
  PraxonCloud_isConfigured,
  PraxonCloud_onAuthStateChange,
  PraxonCloud_sendMagicLink,
  PraxonCloud_signOut,
  PraxonCloud_uploadSnapshot,
} from "../lib/supabase";
import { Thunk_replaceStorageFromSnapshot } from "../ducks/thunks";

interface IProps {
  dispatch: IDispatch;
  storage: IStorage;
  lastSyncedStorage?: IStorage;
  deviceId?: string;
}

interface ICloudMessage {
  type: "error" | "success";
  text: string;
}

export function CloudSyncSection(props: IProps): JSX.Element {
  const [email, setEmail] = useState("");
  const [sessionEmail, setSessionEmail] = useState<string>();
  const [latestSnapshotAt, setLatestSnapshotAt] = useState<string>();
  const [isLoading, setIsLoading] = useState(true);
  const [isSendingLink, setIsSendingLink] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isRestoring, setIsRestoring] = useState(false);
  const [isSigningOut, setIsSigningOut] = useState(false);
  const [message, setMessage] = useState<ICloudMessage>();

  const refreshCloudState = async (): Promise<void> => {
    if (!PraxonCloud_isConfigured()) {
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    try {
      const session = await PraxonCloud_getSession();
      const nextEmail = session?.user.email ?? undefined;
      setSessionEmail(nextEmail);
      if (nextEmail != null) {
        const snapshot = await PraxonCloud_getLatestSnapshot();
        setLatestSnapshotAt(snapshot?.updated_at);
      } else {
        setLatestSnapshotAt(undefined);
      }
    } catch (error) {
      setMessage({
        type: "error",
        text: error instanceof Error ? error.message : "Failed to load Praxon Cloud state.",
      });
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    void refreshCloudState();
    const subscription = PraxonCloud_onAuthStateChange((session) => {
      setSessionEmail(session?.user.email ?? undefined);
      setMessage(
        session?.user.email
          ? { type: "success", text: `Signed in as ${session.user.email}` }
          : { type: "success", text: "Signed out of Praxon Cloud." }
      );
      void refreshCloudState();
    });
    return () => subscription?.unsubscribe();
  }, []);

  if (!PraxonCloud_isConfigured()) {
    return (
      <>
        <GroupHeader name="Cloud" topPadding={true} />
        <MenuItemWrapper name="cloud-unavailable">
          <div className="py-3 text-sm text-text-secondary">
            Praxon Cloud is not configured yet. Set <code>SUPABASE_URL</code> and <code>SUPABASE_ANON_KEY</code> for
            the web app build, then run the SQL in <code>supabase/schema.sql</code>.
          </div>
        </MenuItemWrapper>
      </>
    );
  }

  return (
    <>
      <GroupHeader name="Cloud" topPadding={true} />
      <MenuItemEditable
        type="text"
        name="Cloud Email"
        value={email}
        nextLine={
          <div style={{ marginTop: "-0.5rem" }} className="pb-1 text-xs text-text-secondary">
            Send a magic link to sign in and keep your local data backed up online.
          </div>
        }
        onChange={(newValue) => setEmail(newValue || "")}
      />
      <MenuItemWrapper name="cloud-status">
        <div className="py-3 text-sm">
          {isLoading ? (
            <span className="text-text-secondary">Checking Praxon Cloud...</span>
          ) : sessionEmail ? (
            <div className="space-y-1">
              <div>Signed in as {sessionEmail}</div>
              <div className="text-text-secondary">
                Latest cloud snapshot: {latestSnapshotAt ? formatTimestamp(latestSnapshotAt) : "none yet"}
              </div>
            </div>
          ) : (
            <span className="text-text-secondary">Not signed in. Your workouts stay local until you connect.</span>
          )}
        </div>
      </MenuItemWrapper>
      {message && (
        <MenuItemWrapper name="cloud-message">
          <div className={`py-3 text-sm ${message.type === "error" ? "text-red-500" : "text-text-secondary"}`}>
            {message.text}
          </div>
        </MenuItemWrapper>
      )}
      {!sessionEmail ? (
        <MenuItemWrapper name="cloud-send-link">
          <div className="flex gap-2 py-3">
            <Button
              kind="purple"
              buttonSize="md"
              name="cloud-send-magic-link"
              disabled={isSendingLink || email.trim().length === 0}
              onClick={async () => {
                setIsSendingLink(true);
                setMessage(undefined);
                try {
                  await PraxonCloud_sendMagicLink(email.trim());
                  setMessage({
                    type: "success",
                    text: `Magic link sent to ${email.trim()}. Open it on this device to connect Praxon Cloud.`,
                  });
                } catch (error) {
                  setMessage({
                    type: "error",
                    text: error instanceof Error ? error.message : "Failed to send magic link.",
                  });
                } finally {
                  setIsSendingLink(false);
                }
              }}
            >
              {isSendingLink ? "Sending..." : "Email Magic Link"}
            </Button>
          </div>
        </MenuItemWrapper>
      ) : (
        <MenuItemWrapper name="cloud-actions">
          <div className="flex flex-wrap gap-2 py-3">
            <Button
              kind="purple"
              buttonSize="md"
              name="cloud-upload"
              disabled={isUploading}
              onClick={async () => {
                setIsUploading(true);
                setMessage(undefined);
                try {
                  const snapshot = await PraxonCloud_uploadSnapshot({
                    storage: props.storage,
                    lastSyncedStorage: props.lastSyncedStorage,
                    deviceId: props.deviceId,
                  });
                  setLatestSnapshotAt(snapshot.updated_at);
                  setMessage({
                    type: "success",
                    text: `Uploaded current Praxon data to the cloud at ${formatTimestamp(snapshot.updated_at)}.`,
                  });
                } catch (error) {
                  setMessage({
                    type: "error",
                    text: error instanceof Error ? error.message : "Cloud upload failed.",
                  });
                } finally {
                  setIsUploading(false);
                }
              }}
            >
              {isUploading ? "Uploading..." : "Upload Backup"}
            </Button>
            <Button
              kind="lightgrayv3"
              buttonSize="md"
              name="cloud-restore"
              disabled={isRestoring}
              onClick={async () => {
                if (!confirm("Restore the latest Praxon Cloud snapshot and replace the current local data?")) {
                  return;
                }
                setIsRestoring(true);
                setMessage(undefined);
                try {
                  const snapshot = await PraxonCloud_getLatestSnapshot();
                  if (snapshot == null) {
                    setMessage({ type: "error", text: "No cloud snapshot exists for this account yet." });
                    return;
                  }
                  props.dispatch(
                    Thunk_replaceStorageFromSnapshot(
                      snapshot.storage,
                      `Restored cloud snapshot from ${formatTimestamp(snapshot.updated_at)}.`
                    )
                  );
                } catch (error) {
                  setMessage({
                    type: "error",
                    text: error instanceof Error ? error.message : "Cloud restore failed.",
                  });
                } finally {
                  setIsRestoring(false);
                }
              }}
            >
              {isRestoring ? "Restoring..." : "Restore Latest"}
            </Button>
            <Button
              kind="grayv2"
              buttonSize="md"
              name="cloud-signout"
              disabled={isSigningOut}
              onClick={async () => {
                setIsSigningOut(true);
                setMessage(undefined);
                try {
                  await PraxonCloud_signOut();
                  setLatestSnapshotAt(undefined);
                } catch (error) {
                  setMessage({
                    type: "error",
                    text: error instanceof Error ? error.message : "Failed to sign out of Praxon Cloud.",
                  });
                } finally {
                  setIsSigningOut(false);
                }
              }}
            >
              {isSigningOut ? "Signing out..." : "Sign Out"}
            </Button>
          </div>
        </MenuItemWrapper>
      )}
    </>
  );
}

function formatTimestamp(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return date.toLocaleString();
}
