import { JSX } from "react";
import { IDispatch } from "../ducks/types";
import { IProgram, ISettings, IStats } from "../types";
import { INavCommon } from "../models/state";
import {
  Program_evaluate,
  Program_getListOfDays,
  Program_getProgramDay,
  Program_getProgramDayUsedExercises,
} from "../models/program";
import { Surface } from "./surface";
import { NavbarView } from "./navbar";
import { Footer2View } from "./footer2";
import { Button } from "./button";
import { EditProgram_setNextDay } from "../models/editProgram";
import { Thunk_pushScreen, Thunk_pushToEditProgram, Thunk_startProgramDay } from "../ducks/thunks";
import { PlanDayUtils_findCalendarDay } from "./planDayUtils";
import { Exercise_fullName, Exercise_get } from "../models/exercise";
import { Markdown } from "./markdown";

interface IProps {
  dispatch: IDispatch;
  navCommon: INavCommon;
  program: IProgram;
  settings: ISettings;
  stats: IStats;
}

export function ScreenWeek(props: IProps): JSX.Element {
  const evaluatedProgram = Program_evaluate(props.program, props.settings);
  const calendarDay = PlanDayUtils_findCalendarDay(evaluatedProgram);
  const activeProgress = props.navCommon.progress?.programId === props.program.id ? props.navCommon.progress : undefined;
  const days = Program_getListOfDays(evaluatedProgram).map(([, label], index) => {
    const dayNumber = index + 1;
    return {
      dayNumber,
      label,
      day: Program_getProgramDay(evaluatedProgram, dayNumber),
      isUpNext: dayNumber === evaluatedProgram.nextDay,
      isCalendarToday: dayNumber === calendarDay,
      isOngoing: activeProgress?.day === dayNumber,
    };
  });

  return (
    <Surface
      navbar={
        <NavbarView
          navCommon={props.navCommon}
          dispatch={props.dispatch}
          title="This Week"
          subtitle={props.program.name}
          rightButtons={[
            <Button
              key="advanced-editor"
              kind="lightgrayv3"
              buttonSize="sm"
              className="text-xs"
              name="week-advanced-editor"
              onClick={() => props.dispatch(Thunk_pushToEditProgram())}
            >
              Advanced
            </Button>,
          ]}
        />
      }
      footer={<Footer2View navCommon={props.navCommon} dispatch={props.dispatch} />}
    >
      <section className="px-4 pb-6">
        <div className="pt-1 pb-4 text-sm text-text-secondary">
          Pick the day you want to train, set it as next, or jump straight into the advanced editor for detailed edits.
        </div>
        {props.program.description && (
          <section className="p-4 mb-4 border rounded-2xl bg-background-cardpurple border-border-cardpurple">
            <div className="text-sm font-semibold text-text-primary">Plan Notes</div>
            <div className="mt-3 text-sm">
              <Markdown value={props.program.description} />
            </div>
          </section>
        )}
        <div className="space-y-4">
          {days.map((dayInfo) => {
            const exercises = dayInfo.day ? Program_getProgramDayUsedExercises(dayInfo.day) : [];
            const canStart = !activeProgress || dayInfo.isOngoing;
            return (
              <section
                key={dayInfo.dayNumber}
                className={`p-4 border rounded-2xl ${
                  dayInfo.isUpNext
                    ? "bg-background-cardpurple border-border-cardpurple"
                    : "bg-background-default border-border-neutral"
                }`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <div className="font-semibold text-text-primary">{dayInfo.label}</div>
                    <div className="text-xs text-text-secondary">
                      {exercises.length} exercises
                      {dayInfo.isCalendarToday ? " · Calendar today" : ""}
                      {dayInfo.isUpNext ? " · Up next" : ""}
                      {dayInfo.isOngoing ? " · Ongoing" : ""}
                    </div>
                  </div>
                  <Button
                    kind="lightgrayv3"
                    buttonSize="sm"
                    name={`week-edit-day-${dayInfo.dayNumber}`}
                    onClick={() => props.dispatch(Thunk_pushScreen("weekDayEditor", { day: dayInfo.dayNumber }))}
                  >
                    Edit
                  </Button>
                </div>

                <div className="mt-3 space-y-2">
                  {dayInfo.day?.description && (
                    <div className="p-3 text-sm border rounded-xl bg-background-subtle border-border-neutral">
                      <Markdown value={dayInfo.day.description} />
                    </div>
                  )}
                  {exercises.length > 0 ? (
                    exercises.slice(0, 6).map((exercise) => (
                      <div key={exercise.key} className="text-sm text-text-primary">
                        {Exercise_fullName(Exercise_get(exercise.exerciseType, props.settings.exercises), props.settings)}
                      </div>
                    ))
                  ) : (
                    <div className="text-sm text-text-secondary">No exercises planned for this day yet.</div>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-2 mt-4">
                  <Button
                    kind="purple"
                    name={`week-start-day-${dayInfo.dayNumber}`}
                    disabled={!canStart}
                    onClick={() => {
                      if (!activeProgress) {
                        EditProgram_setNextDay(props.dispatch, props.program.id, dayInfo.dayNumber);
                      }
                      props.dispatch(Thunk_startProgramDay(props.program.id));
                    }}
                  >
                    {dayInfo.isOngoing ? "Continue" : "Start"}
                  </Button>
                  <Button
                    kind="grayv2"
                    name={`week-set-next-${dayInfo.dayNumber}`}
                    disabled={dayInfo.isUpNext}
                    onClick={() => EditProgram_setNextDay(props.dispatch, props.program.id, dayInfo.dayNumber)}
                  >
                    {dayInfo.isUpNext ? "Up Next" : "Set As Next"}
                  </Button>
                </div>
              </section>
            );
          })}
        </div>
      </section>
    </Surface>
  );
}
